package planorder

import (
	"errors"
	"sort"
	"strings"
)

var errBad = errors.New("planorder: bad input")

func validName(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		alnum := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
		if i == 0 && !alnum {
			return false
		}
		if !alnum && c != '_' && c != '.' && c != '-' {
			return false
		}
	}
	return true
}

type plan struct {
	names []string
	deps  map[string][]string
}

func parse(steps []string) (*plan, error) {
	p := &plan{deps: map[string][]string{}}
	for _, s := range steps {
		name, rest, _ := strings.Cut(s, ":")
		if !validName(name) {
			return nil, errBad
		}
		if _, dup := p.deps[name]; dup {
			return nil, errBad
		}
		ds := []string{}
		if rest != "" {
			for _, d := range strings.Split(rest, ",") {
				if !validName(d) {
					return nil, errBad
				}
				dupDep := false
				for _, e := range ds {
					if e == d {
						dupDep = true
					}
				}
				if !dupDep {
					ds = append(ds, d)
				}
			}
		}
		p.deps[name] = ds
		p.names = append(p.names, name)
	}
	for _, ds := range p.deps {
		for _, d := range ds {
			if _, ok := p.deps[d]; !ok {
				return nil, errBad
			}
		}
	}
	return p, nil
}

func (p *plan) order() ([]string, error) {
	remaining := map[string]map[string]bool{}
	for n, ds := range p.deps {
		set := map[string]bool{}
		for _, d := range ds {
			set[d] = true
		}
		remaining[n] = set
	}
	out := []string{}
	for len(remaining) > 0 {
		var ready []string
		for n, ds := range remaining {
			if len(ds) == 0 {
				ready = append(ready, n)
			}
		}
		if len(ready) == 0 {
			return nil, errors.New("planorder: cycle")
		}
		sort.Strings(ready)
		pick := ready[0]
		out = append(out, pick)
		delete(remaining, pick)
		for _, ds := range remaining {
			delete(ds, pick)
		}
	}
	return out, nil
}

func BuildOrder(steps []string) ([]string, error) {
	p, err := parse(steps)
	if err != nil {
		return nil, err
	}
	return p.order()
}

func Layers(steps []string) ([][]string, error) {
	p, err := parse(steps)
	if err != nil {
		return nil, err
	}
	order, err := p.order()
	if err != nil {
		return nil, err
	}
	depth := map[string]int{}
	for _, n := range order {
		d := 0
		for _, dep := range p.deps[n] {
			if depth[dep]+1 > d {
				d = depth[dep] + 1
			}
		}
		depth[n] = d
	}
	names := append([]string(nil), p.names...)
	sort.Strings(names)
	out := [][]string{}
	for _, n := range names {
		for len(out) <= depth[n] {
			out = append(out, []string{})
		}
		out[depth[n]] = append(out[depth[n]], n)
	}
	return out, nil
}

func Blockers(steps []string, name string) ([]string, error) {
	p, err := parse(steps)
	if err != nil {
		return nil, err
	}
	if _, err := p.order(); err != nil {
		return nil, err
	}
	if _, ok := p.deps[name]; !ok {
		return nil, errBad
	}
	seen := map[string]bool{}
	stack := append([]string(nil), p.deps[name]...)
	for len(stack) > 0 {
		d := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if !seen[d] {
			seen[d] = true
			stack = append(stack, p.deps[d]...)
		}
	}
	out := []string{}
	for d := range seen {
		out = append(out, d)
	}
	sort.Strings(out)
	return out, nil
}

func ReadyAfter(steps []string, done []string) ([]string, error) {
	p, err := parse(steps)
	if err != nil {
		return nil, err
	}
	if _, err := p.order(); err != nil {
		return nil, err
	}
	have := map[string]bool{}
	for _, d := range done {
		if _, ok := p.deps[d]; !ok {
			return nil, errBad
		}
		have[d] = true
	}
	out := []string{}
	for _, n := range p.names {
		if have[n] {
			continue
		}
		ok := true
		for _, d := range p.deps[n] {
			if !have[d] {
				ok = false
			}
		}
		if ok {
			out = append(out, n)
		}
	}
	sort.Strings(out)
	return out, nil
}

