package planorder

import (
	"errors"
	"sort"
	"strings"
)

var errBad = errors.New("planorder: bad input")

func validName(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		alnum := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
		if i == 0 && !alnum {
			return false
		}
		if !alnum && c != '_' && c != '.' && c != '-' {
			return false
		}
	}
	return true
}

type plan struct {
	names []string
	deps  map[string][]string
}

func parse(steps []string) (*plan, error) {
	p := &plan{deps: map[string][]string{}}
	for _, s := range steps {
		name, rest, _ := strings.Cut(s, ":")
		if !validName(name) {
			return nil, errBad
		}
		if _, dup := p.deps[name]; dup {
			return nil, errBad
		}
		ds := []string{}
		if rest != "" {
			for _, d := range strings.Split(rest, ",") {
				if !validName(d) {
					return nil, errBad
				}
				dupDep := false
				for _, e := range ds {
					if e == d {
						dupDep = true
					}
				}
				if !dupDep {
					ds = append(ds, d)
				}
			}
		}
		p.deps[name] = ds
		p.names = append(p.names, name)
	}
	for _, ds := range p.deps {
