	p, err := parse(steps)
	if err != nil {
		return nil, err
	}
	if _, err := p.order(); err != nil {
		return nil, err
	}
	if _, ok := p.deps[name]; !ok {
		return nil, errBad
	}
	seen := map[string]bool{}
	stack := append([]string(nil), p.deps[name]...)
	for len(stack) > 0 {
		d := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if !seen[d] {
			seen[d] = true
			stack = append(stack, p.deps[d]...)
		}
	}
	out := []string{}
	for d := range seen {
		out = append(out, d)
	}
	sort.Strings(out)
	return out, nil
}

func ReadyAfter(steps []string, done []string) ([]string, error) {
	p, err := parse(steps)
