		if _, ok := p.deps[d]; !ok {
			return nil, errBad
		}
		have[d] = true
	}
	out := []string{}
	for _, n := range p.names {
		if have[n] {
			continue
		}
		ok := true
		for _, d := range p.deps[n] {
			if !have[d] {
				ok = false
			}
		}
		if ok {
			out = append(out, n)
		}
	}
	sort.Strings(out)
	return out, nil
}

